def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                        (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            objs.append((color, cells))

    # Move rightmost objects first, each as far right as it can go.
    objs.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    occupied = set()
    positions = []
    for color, cells in objs:
        cells = set(cells)
        shift = 0
        while True:
            candidate = {(r, c + shift + 1) for r, c in cells}
            if any(c >= w for _, c in candidate) or candidate & occupied:
                break
            shift += 1
        moved = {(r, c + shift) for r, c in cells}
        occupied |= moved
        positions.append((color, moved))

    out = [[0] * w for _ in range(h)]
    for color, cells in positions:
        for r, c in cells:
            out[r][c] = color
    return out
